using System.Data;
using System.Web;

// Compatibility wrapper: BaoCaoBOMHHVT2.aspx.cs still calls this class.
// The actual export is a native .xlsx generated by BomHhvtXlsxExporter.
public static class BomHhvtSpreadsheetMlExporter
{
    public static void Export(HttpResponse response, DataTable matrix)
    {
        BomHhvtXlsxExporter.Export(response, matrix);

        // CompleteRequest() does not stop the WebForms page from rendering.
        // Without End(), the page HTML is appended after the XLSX ZIP end record,
        // so Excel/LibreOffice reports the file as corrupt and repairs it.
        response.End();
    }
}
